fsharp.Solution.fs:
module Solution

// One row has four seats. This implementation knows only our examples.
let seats (rows: int) : int =
    if rows = 1 then 4
    elif rows = 2 then 8
    else 0

fsharp.Tests.fs:
module Tests
open Solution

// Each pair gives a name and a Boolean observation.
let examples () : (string * bool) array =
    [| "one row", seats 1 = 4
       "two rows", seats 2 = 8 |]

// A generated row count must obey the same rule.
let property (rows: int) : bool = seats rows = rows * 4

let regressions : (string * bool) array = [||]

javascript.Solution.js:
export function seats(rows) {
  return rows === 1 ? 4 : rows === 2 ? 8 : 0;
}

javascript.Tests.js:
import { seats } from "./Solution.js";
export const examples = () => [["one row", seats(1) === 4], ["two rows", seats(2) === 8]];
export const property = rows => seats(rows) === rows * 4;

export const regressions = [];

