fsharp.Solution.fs:
module Solution

let unique (xs: int list) : int list =
    xs |> List.filter (fun x -> x <> 0) |> List.distinct

javascript.Tests.js:
import { unique } from "./Solution.js";
export const examples = () => [["repeated ticket", JSON.stringify(unique([2,2,3])) === "[2,3]"]];
export const property = xs => JSON.stringify([...unique(xs)].sort((a,b)=>a-b)) === JSON.stringify([...new Set(xs)].sort((a,b)=>a-b));

export const regressions = [];

